import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易集注 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易集注 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"zh/classics/jizhu/043.md","filePath":"zh/classics/jizhu/043.md"}'),h={name:"zh/classics/jizhu/043.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>蹇难也，为卦艮下坎上。坎险艮止，险在前，见险而止，不能前进，蹇之义也。《序卦》：睽者乖也，乖必有难，故受之以蹇，所以次睽。</p><p>蹇难在东北，文王圆图，艮坎皆在东北也。若西南则无难矣，所以利西南。大人者九五也。旧注：坤方体顺而易，艮方体止而险。又云：西南平易，东北险阻，皆始于王弼。弼曰“西南为地，东北为山”，后儒从之，遂生此说，而不知文王卦辞，乃与解卦相综也。</p><p>《彖》曰：蹇，难也，险在前也。见险而能止，知矣哉!蹇利西南，往得中也;不利东北，其道穷也;利见大人，往有功也;当位贞吉，以正邦也。蹇之时用大矣哉!难乃旦反。知音智</p><p>以卦德卦综卦体释卦名卦辞而赞之。难者，行不进之义也。坎之德为险，居卦之前，不可前进，此所以名为蹇也。然艮止在后，止之而不冒其险，明哲保身者也，不其智哉。往得中者，蹇综解，二卦同体，文王综为一卦，故《杂卦》曰：“解缓也，蹇难也。”言解下卦之坎，往而为蹇上卦之坎，所以九五得其中也。讼卦，刚来而得中者，坎自需上卦来，故曰来。此卦解自下卦往，故曰往。其道穷者，解上卦之震。下而为蹇，下卦之艮也。蹇难在东北，今下于东北，又艮止不行，所以其道穷。文王圆图，东北居圆图之下，西南居圆图之上，故往而上者，则入西南之境矣，故往得中。来而下者，则入东北之境矣，故其道穷。往有功之往，即往得中之往，故利见九五大人，则往有功。当位者，阳刚皆当其位也。八卦正位，坎在五，艮在三，今二卦阳刚，皆得正位，有贞之义，故贞吉。渐卦巽艮，男女皆得正位，故彖辞同。若以人事论，往得中者，是所往得其地，据形胜而得所安也。若非其地，其道穷矣。往有功者，所依得其人也。盖阳刚中正，以居尊位，则其德足以联属天下之心，其势足以汲引天下之士，故往有功。正邦者，所处得其正，正则行一不义、杀一不辜而不为，所以能明信义于天下，而邦其底定矣。有此三者，方可济蹇。故叹其时用之大，与坎睽同。</p><h3 id="《象》曰-山上有水-蹇-君子以反身修德。" tabindex="-1">《象》曰：山上有水，蹇，君子以反身修德。 <a class="header-anchor" href="#《象》曰-山上有水-蹇-君子以反身修德。" aria-label="Permalink to “《象》曰：山上有水，蹇，君子以反身修德。”">​</a></h3><p>山上有水，为山所阻，不得施行，蹇之象也。君子以行，有不得者，乃此身之蹇也。若怨天尤人，安能济其蹇，惟反身修德，则诚能动物，家邦必达矣。此善于济此身之蹇者也。</p><p>初六，往蹇来誉。</p><p>往来者，进退二字也。本卦，蹇字从足，艮综震，震为足，故诸爻皆以往来言之。誉者，有智矣哉之誉也。往以坎言，上进则为往，入于坎矣。来以艮言，不进则为来，艮而止矣。</p><p>六非济蹇之才，初非济蹇之位。故有进而往则冒其蹇，退而来则来其誉之象。占者遇此，亦当有待也。</p><h3 id="《象》曰-往蹇来誉-宜待也。" tabindex="-1">《象》曰：往蹇来誉，宜待也。 <a class="header-anchor" href="#《象》曰-往蹇来誉-宜待也。" aria-label="Permalink to “《象》曰：往蹇来誉，宜待也。”">​</a></h3><p>待者，待其时之可进也。</p><p>六二，王臣蹇蹇，匪躬之故。</p><p>王者五也，臣者二也。外卦之坎，王之蹇也。中爻之坎，臣之蹇也。因二五在两坎之中，故以两蹇字言之。六二艮体有不获其身之象，故言匪躬。匪躬者，不有其身也。言王臣皆在坎陷之中，蹇而又蹇，不能济其蹇。六二不有其身者，因此蹇蹇之故也。张巡许远此爻近之。</p><p>六二当国家蹇难之时，主忧臣辱，故有王臣蹇蹇之象。然六二柔顺中正，盖事君能致其身者也，故又有匪躬之象。占者得此，成败利钝非所论矣。</p><h3 id="《象》曰-王臣蹇蹇-终无尤也。" tabindex="-1">《象》曰：王臣蹇蹇，终无尤也。 <a class="header-anchor" href="#《象》曰-王臣蹇蹇-终无尤也。" aria-label="Permalink to “《象》曰：王臣蹇蹇，终无尤也。”">​</a></h3><p>力虽不济，心已捐生，有何尤。初六以不往为有誉，六二以匪躬为无尤，有位无位之间耳。</p><p>九三，往蹇来反。</p><p>来反者，来反而比于二也。此爻变坤，为水地比。来反者，亲比于人之象也。六二忠贞之臣，但其才柔，不能济蹇，蹇而又蹇，思刚明之人以协助之，乃其本心，所以喜其反也。</p><p>九三阳刚得正，当蹇之时，与上六为正应，但为五所隔，故来反而比于同体之二，三则资其二之巽顺。二则资其三之刚明，可以济蹇之功矣。故有往则蹇而来反之象，占者得此亦宜反也。</p><h3 id="《象》曰-往蹇来反-内喜之也。" tabindex="-1">《象》曰：往蹇来反，内喜之也。 <a class="header-anchor" href="#《象》曰-往蹇来反-内喜之也。" aria-label="Permalink to “《象》曰：往蹇来反，内喜之也。”">​</a></h3><p>内者，内卦之二也，二之阴乐于从阳，故喜之。</p><p>六四，往蹇来连。</p><p>连者相连也。许远当禄山之乱，乃对张巡曰：君才十倍于远。由是帷帐之谋，一断于巡，此六四之来连者也。六二喜之者，内之兄弟，喜其己之有助也。六四连之者，外之朋友，喜其人之有才也。</p><p>六四近君，当济蹇矣，但六四以阴柔之才，无拨乱兴衰之略，于是来连于九三，合力以济，故其象如此，占者凡事亲贤而后可。</p><h3 id="《象》曰-往蹇来连-当位实也。" tabindex="-1">《象》曰：往蹇来连，当位实也。 <a class="header-anchor" href="#《象》曰-往蹇来连-当位实也。" aria-label="Permalink to “《象》曰：往蹇来连，当位实也。”">​</a></h3><p>阳实阴虚，实指九三，与独远实之实同。当位实者，言九三得八卦之正位，实当其位也。阳刚得其正位，则才足以有为，可以济蹇矣。</p><p>九五，大蹇，朋来。</p><p>阳大阴小，大者阳也，即九五也，言九五之君蹇也。朋指三，即九五同德之阳，三与五同功异位者也。上六来硕，应乎三者也。六四来连，比乎三者也。三有刚实之才，惟三可以济蹇，然三与五非比非应，不能从乎其五，惟二与五应，乃君臣同其患难者，馀四爻则不当其责者也。朋来合乎二以济蹇，则诸爻皆共济其蹇矣。自下而上曰往，自上而下曰来。今曰朋来，则知六四三皆来合乎二也。朋来之来，即来反之来。此爻变坤，坤为众，朋之象也。自本爻言之，所谓当位贞吉，以正邦也。自上下诸爻言之，所谓利见大人，往有功也。所以大蹇朋来。</p><p>九五居尊，有阳刚中正之德。当蹇难之时，下应六二，六二固匪躬矣，而为三者，又来反乎二而济蹇，三之朋既来，则凡应乎朋而来硕，比乎朋而来连，皆翕然并至，以共济其蹇矣，故有大蹇朋来之象。占者有是德，方应是占也。</p><h3 id="《象》曰-大蹇朋来-以中节也。" tabindex="-1">《象》曰：大蹇朋来，以中节也。 <a class="header-anchor" href="#《象》曰-大蹇朋来-以中节也。" aria-label="Permalink to “《象》曰：大蹇朋来，以中节也。”">​</a></h3><p>中者中德也，即刚健中正之德也。节者，节制也。言为五者，有刚健之中德，足以联属之。有九五之尊位，足以节制之，所以大蹇朋来也。</p><p>上六，往蹇来硕，吉，利见大人。</p><p>硕者大也，阳大阴小，故言大。不言大而言硕者，九五已有大字矣。来硕者，来就三也。吉者，诸爻皆未能济蹇，此独能济也。见大人者，见九五也。</p><p>上六才柔不能济蹇，且居卦极，往无所之，益以蹇耳。九三乃阳刚当位众志之所乐从者，反而就之，则可以共济其蹇矣。何吉如之?若此者，非因人成事也。以九五大人之君，方在蹇中，上与三利见之，共济其蹇，则往有功矣，此其所以吉也。故占者来硕则吉，而见大人则利也。若旧注：来就九五，则见大人，为重复矣，且《小象》曰：志在内也，若就九五，则志在外卦，不在内卦矣。</p><h3 id="《象》曰-往蹇来硕-志在内也-利见大人-以从贵也。" tabindex="-1">《象》曰：往蹇来硕，志在内也;利见大人，以从贵也。 <a class="header-anchor" href="#《象》曰-往蹇来硕-志在内也-利见大人-以从贵也。" aria-label="Permalink to “《象》曰：往蹇来硕，志在内也;利见大人，以从贵也。”">​</a></h3><p>内指九三，对外卦而言则曰内。贵指九五，对下贱而言则曰贵。志内所以尚贤，从贵所以严分。</p>',37)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
